package com.example.waterfilter;

import android.Manifest;import android.app.*;import android.content.*;import android.text.InputType;import android.widget.EditText;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.*;import android.widget.Toast;import androidx.core.app.ActivityCompat;import androidx.core.content.ContextCompat;import androidx.core.content.FileProvider;import org.json.*;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity {
 static final String PREFS="filterprefs",DATA_KEY="stagedata",ENABLED_KEY="notifications_enabled",CHANNEL_ID="filter_reminders",TIME_KEY="reminder_time",DAYS_KEY="reminder_days";
 private WebView webView;private ValueCallback<Uri[]> fileCallback;private Uri cameraImageUri;private String backupJson;private static final int FILE_REQUEST=701,CREATE_BACKUP=702;
 @Override public void onCreate(Bundle b){
  super.onCreate(b);createChannel();webView=new WebView(this);webView.setBackgroundColor(0xFFF2F7FB);
  WebSettings ws=webView.getSettings();ws.setJavaScriptEnabled(true);ws.setDomStorageEnabled(true);ws.setAllowFileAccess(true);ws.setAllowContentAccess(true);ws.setDefaultTextEncodingName("UTF-8");
  webView.setWebViewClient(new WebViewClient());
  webView.setWebChromeClient(new WebChromeClient(){
   @Override public boolean onJsAlert(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("موافق",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}
   @Override public boolean onJsConfirm(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("موافق",(d,w)->result.confirm()).setNegativeButton("إلغاء",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
   @Override public boolean onJsPrompt(WebView view,String url,String message,String defaultValue,JsPromptResult result){EditText input=new EditText(MainActivity.this);input.setText(defaultValue==null?"":defaultValue);input.setSingleLine(true);new AlertDialog.Builder(MainActivity.this).setTitle(message).setView(input).setPositiveButton("موافق",(d,w)->result.confirm(input.getText().toString())).setNegativeButton("إلغاء",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
   @Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams params){
    if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;
    String[] types=params.getAcceptTypes();boolean wantsImage=false;
    if(types!=null)for(String t:types)if(t!=null&&t.toLowerCase(Locale.ROOT).startsWith("image/")){wantsImage=true;break;}
    if(!wantsImage){launchGallery("*/*");return true;}
    new AlertDialog.Builder(MainActivity.this).setTitle("اختيار صورة الشمعة")
      .setItems(new String[]{"التصوير بالكاميرا","اختيار من الاستديو"},(dialog,which)->{if(which==0)launchCamera();else launchGallery("image/*");})
      .setOnCancelListener(dialog->finishFileSelection(null)).show();
    return true;
   }
  });
  webView.addJavascriptInterface(new AndroidBridge(),"AndroidBridge");setContentView(webView);webView.loadUrl("file:///android_asset/index.html");
  if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.POST_NOTIFICATIONS},7001);
 }
 private void launchGallery(String type){try{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type);startActivityForResult(Intent.createChooser(i,"اختار صورة من الاستديو"),FILE_REQUEST);}catch(Exception e){finishFileSelection(null);Toast.makeText(this,"تعذر فتح الاستديو",Toast.LENGTH_LONG).show();}}
 private void launchCamera(){try{Intent i=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);if(i.resolveActivity(getPackageManager())==null){finishFileSelection(null);Toast.makeText(this,"مفيش تطبيق كاميرا متاح",Toast.LENGTH_LONG).show();return;}File dir=new File(getCacheDir(),"images");if(!dir.exists()&&!dir.mkdirs())throw new IOException("camera cache");File photo=File.createTempFile("filter_camera_", ".jpg",dir);cameraImageUri=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",photo);i.putExtra(android.provider.MediaStore.EXTRA_OUTPUT,cameraImageUri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);i.setClipData(android.content.ClipData.newUri(getContentResolver(),"Camera photo",cameraImageUri));startActivityForResult(i,FILE_REQUEST);}catch(Exception e){finishFileSelection(null);Toast.makeText(this,"تعذر تشغيل الكاميرا",Toast.LENGTH_LONG).show();}}
 private void finishFileSelection(Uri[] result){if(fileCallback!=null){fileCallback.onReceiveValue(result);fileCallback=null;}cameraImageUri=null;}
 @Override protected void onActivityResult(int req,int result,Intent data){
  super.onActivityResult(req,result,data);
  if(req==FILE_REQUEST){Uri[] resultUris=null;if(result==RESULT_OK){Uri selected=(data!=null&&data.getData()!=null)?data.getData():cameraImageUri;if(selected!=null)resultUris=new Uri[]{selected};}finishFileSelection(resultUris);}
  else if(req==CREATE_BACKUP&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(OutputStream os=getContentResolver().openOutputStream(data.getData())){os.write((backupJson==null?"{}":backupJson).getBytes("UTF-8"));Toast.makeText(this,"تم حفظ النسخة الاحتياطية",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"فشل حفظ النسخة الاحتياطية",Toast.LENGTH_LONG).show();}}
 }
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL_ID,"تذكيرات فلتر المياه",NotificationManager.IMPORTANCE_HIGH);c.setDescription("تذكيرات مواعيد تغيير شمعات فلتر المياه");c.enableVibration(true);getSystemService(NotificationManager.class).createNotificationChannel(c);}}
 public class AndroidBridge{
  @JavascriptInterface public boolean getNotificationsEnabled(){return getSharedPreferences(PREFS,0).getBoolean(ENABLED_KEY,true);}
  @JavascriptInterface public void setNotificationsEnabled(boolean e){getSharedPreferences(PREFS,0).edit().putBoolean(ENABLED_KEY,e).commit();if(e)scheduleAll(MainActivity.this,getSharedPreferences(PREFS,0).getString(DATA_KEY,"[]"));else cancelAll(MainActivity.this);}
  @JavascriptInterface public void updateSchedule(String json){getSharedPreferences(PREFS,0).edit().putString(DATA_KEY,json).commit();if(getNotificationsEnabled())scheduleAll(MainActivity.this,json);}
  @JavascriptInterface public void updateReminderSettings(String time,String days){SharedPreferences p=getSharedPreferences(PREFS,0);try{JSONArray arr=new JSONArray(days==null?"[]":days);ArrayList<Integer> clean=new ArrayList<>();for(int i=0;i<arr.length();i++){int n=arr.optInt(i,-1);if(n>=1&&n<=60&&!clean.contains(n))clean.add(n);}clean.sort(Collections.reverseOrder());JSONArray normalized=new JSONArray();for(int n:clean)normalized.put(n);String safeTime=(time!=null&&time.matches("(?:[01]\\d|2[0-3]):[0-5]\\d"))?time:"09:00";p.edit().putString(TIME_KEY,safeTime).putString(DAYS_KEY,normalized.toString()).commit();if(p.getBoolean(ENABLED_KEY,true))scheduleAll(MainActivity.this,p.getString(DATA_KEY,"[]"));}catch(Exception e){android.util.Log.e("WaterFilter","Invalid reminder settings",e);}}
  @JavascriptInterface public String getReminderSettings(){SharedPreferences p=getSharedPreferences(PREFS,0);org.json.JSONObject o=new org.json.JSONObject();try{o.put("time",p.getString(TIME_KEY,"09:00"));o.put("days",p.getString(DAYS_KEY,"[7,2]"));}catch(Exception ignored){}return o.toString();}
  @JavascriptInterface public void saveBackup(String json){runOnUiThread(()->{backupJson=json;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"نسخة-فلتر-المياه-"+new SimpleDateFormat("yyyyMMdd-HHmm",Locale.US).format(new Date())+".json");startActivityForResult(i,CREATE_BACKUP);});}
  @JavascriptInterface public void testNotification(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(MainActivity.this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(MainActivity.this,new String[]{Manifest.permission.POST_NOTIFICATIONS},7001);Toast.makeText(MainActivity.this,"اسمح بإشعارات التطبيق ثم جرّب مرة أخرى",Toast.LENGTH_LONG).show();return;}ReminderReceiver.showNotification(MainActivity.this,"تجربة إشعار","الإشعارات شغالة في متابع فلتر المياه");});}
  @JavascriptInterface public void openExactAlarmSettings(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=31){try{Intent i=new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Exception e){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}}else Toast.makeText(MainActivity.this,"التنبيهات الدقيقة مدعومة تلقائيًا على هذا الإصدار",Toast.LENGTH_LONG).show();});}
 }
 static void cancelAll(Context c){AlarmManager am=(AlarmManager)c.getSystemService(ALARM_SERVICE);SharedPreferences p=c.getSharedPreferences(PREFS,0);try{JSONArray fs=new JSONArray(p.getString(DATA_KEY,"[]"));for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i);JSONArray ss=f.optJSONArray("stages");if(ss==null)continue;for(int j=0;j<ss.length();j++){JSONObject st=ss.getJSONObject(j);int base=requestBase(f.optString("id","f"+i),st.optString("id","s"+j));for(int k=0;k<64;k++){PendingIntent pi=makePending(c,base+k,"","");am.cancel(pi);pi.cancel();}}}}catch(Exception ignored){}}
 static void scheduleAll(Context c,String json){SharedPreferences p=c.getSharedPreferences(PREFS,0);if(!p.getBoolean(ENABLED_KEY,true))return;AlarmManager am=(AlarmManager)c.getSystemService(ALARM_SERVICE);cancelAll(c);try{JSONArray fs=new JSONArray(json);String[] hm=p.getString(TIME_KEY,"09:00").split(":");int hour=Integer.parseInt(hm[0]),minute=Integer.parseInt(hm[1]);JSONArray days=new JSONArray(p.getString(DAYS_KEY,"[7,2]"));ArrayList<Integer> leads=new ArrayList<>();for(int x=0;x<days.length();x++){int n=days.optInt(x,-1);if(n>0&&n<=60&&!leads.contains(n))leads.add(n);}leads.sort(Collections.reverseOrder());for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i);JSONArray ss=f.optJSONArray("stages");if(ss==null)continue;for(int j=0;j<ss.length();j++){JSONObject st=ss.getJSONObject(j);if(!st.optBoolean("active",true))continue;String due=st.optString("dueDate","");if(due.length()<10)continue;Calendar dueCal=Calendar.getInstance();SimpleDateFormat sdf=new SimpleDateFormat("yyyy-MM-dd",Locale.US);Date date=sdf.parse(due.substring(0,10));if(date==null)continue;dueCal.setTime(date);dueCal.set(Calendar.HOUR_OF_DAY,hour);dueCal.set(Calendar.MINUTE,minute);dueCal.set(Calendar.SECOND,0);dueCal.set(Calendar.MILLISECOND,0);int base=requestBase(f.optString("id","f"+i),st.optString("id","s"+j));String stage=st.optString("name","الشمعة"),filter=f.optString("name","فلتر المياه");int idx=0;for(Integer lead:leads){Calendar t=(Calendar)dueCal.clone();t.add(Calendar.DAY_OF_YEAR,-lead);if(t.getTimeInMillis()>System.currentTimeMillis())setAlarm(am,c,t,base+idx++,stage,"متبقي "+lead+" يوم على تغيير "+stage+" في "+filter);}if(dueCal.getTimeInMillis()>System.currentTimeMillis())setAlarm(am,c,dueCal,base+idx++,stage,"حان موعد تغيير "+stage+" في "+filter);Calendar late=(Calendar)dueCal.clone();late.add(Calendar.DAY_OF_YEAR,1);while(late.getTimeInMillis()<=System.currentTimeMillis())late.add(Calendar.DAY_OF_YEAR,1);if(idx<63)setDailyLate(am,c,late,base+idx,stage,"موعد تغيير "+stage+" في "+filter+" فات؛ برجاء تسجيل التغيير");}}}catch(Exception e){android.util.Log.e("WaterFilter","schedule failed",e);}}
 static void setAlarm(AlarmManager am,Context c,Calendar t,int req,String title,String msg){PendingIntent pi=makePending(c,req,title,msg);if(Build.VERSION.SDK_INT>=23){if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);}else am.setExact(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),pi);}
 static void setDailyLate(AlarmManager am,Context c,Calendar t,int req,String title,String msg){PendingIntent pi=makePending(c,req,title,msg);am.setInexactRepeating(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),AlarmManager.INTERVAL_DAY,pi);}
 static int requestBase(String f,String s){return 1000+((f+"|"+s).hashCode()&0x0fffffff)%400000*64;}
 static PendingIntent makePending(Context c,int req,String title,String msg){Intent i=new Intent(c,ReminderReceiver.class);i.putExtra("title",title);i.putExtra("message",msg);int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;return PendingIntent.getBroadcast(c,req,i,flags);}
 @Override protected void onResume(){super.onResume();SharedPreferences p=getSharedPreferences(PREFS,0);if(p.getBoolean(ENABLED_KEY,true))scheduleAll(this,p.getString(DATA_KEY,"[]"));}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
}
